#!/usr/bin/env bash
# Writes docs/traceability.md: one row for each ticket that has a spec. No network, no model.
# Usage (from the repository root): bash .github/scripts/trace.sh
# Reads docs/specs/*.md (Ticket, Intent, requirements R1, R2, ...), docs/qa/<KEY>.md and
# docs/acceptance/*.md (not the milestone records). Where a link is missing the row says
# "no QA record" or "no acceptance"; nothing is guessed. Rows are sorted by ticket key, so a
# rerun on the same files gives the same file. Exit 0: written. Exit 2: no docs/specs.
set -uo pipefail

[ -d docs/specs ] || { echo "no docs/specs here: run from the repository root" >&2; exit 2; }
out="docs/traceability.md"

header() { sed -n "s/^$1:[[:space:]]*\(.*[^[:space:]]\)[[:space:]]*$/\1/p" "$2" | head -1; }
section() { awk -v h="$2" '/^## /{on = (index($0, "## " h) == 1); next} on' "$1"; }
req_ids() { section "$1" "Requirements" | sed -n 's/^-[[:space:]]*\(R[0-9][0-9]*\)\..*/\1/p'; }
# QA rows as "id<US>requirement<US>result"
rows() {
  section "$1" "Test matrix" | awk '
    function trim(s) { gsub(/^[ \t\r]+|[ \t\r]+$/, "", s); return s }
    /^[ \t]*\|/ {
      if ($0 ~ /^[ \t]*\|[-: |\t]+\|?[ \t\r]*$/) next
      n = split($0, c, "|")
      if (!hdr) { hdr = 1; for (i = 2; i < n; i++) col[trim(c[i])] = i; next }
      print trim(c[col["ID"]]) "\037" trim(c[col["Requirement"]]) "\037" trim(c[col["Result"]])
    }'
}
verdict_word() {
  section "$1" "Verdict" | sed -n '/[^[:space:]]/{s/^[[:space:]]*//;p;q;}' | sed -En 's/^(Accepted|Not accepted|Pending).*/\1/p'
}

# acceptance records: "slug<TAB>outcome<TAB>verdict<TAB>tickets"
acc_list=""
for f in docs/acceptance/*.md; do
  [ -f "$f" ] || continue
  slug=$(basename "$f" .md)
  case "$slug" in milestone-*) continue ;; esac
  acc_list="$acc_list$slug	$(header Outcome "$f")	$(verdict_word "$f")	$(header Tickets "$f" | tr ',' ' ')
"
done

lines=""
for spec in docs/specs/*.md; do
  [ -f "$spec" ] || continue
  key=$(sed -n 's/^Ticket:[[:space:]]*\([A-Za-z0-9_-]*\).*/\1/p' "$spec" | head -1)
  [ -n "$key" ] || continue
  intent=$(sed -n 's/^Intent:[[:space:]]*\([^[:space:]]*\).*/\1/p' "$spec" | head -1)
  [ -n "$intent" ] || intent="no intent"

  outcome="-"; acceptance="no acceptance"
  while IFS='	' read -r slug o v t; do
    [ -n "$slug" ] || continue
    for k in $t; do
      if [ "$k" = "$key" ]; then outcome="${o:--}"; acceptance="${v:-no verdict} ($slug)"; break 2; fi
    done
  done <<< "$acc_list"

  qa="docs/qa/$key.md"
  if [ -f "$qa" ]; then
    reqs=$(req_ids "$spec"); total=$(printf '%s\n' "$reqs" | sed '/^$/d' | wc -l | tr -d ' ')
    covered=0; passed=0; nrows=0; seen=" "
    excused=$(section "$qa" "Not covered" | sed -n 's/^-[[:space:]]*\(R[0-9][0-9]*\)\..*/\1/p')
    while IFS=$'\037' read -r id rq rs; do
      [ -n "$id" ] || continue
      nrows=$((nrows + 1)); [ "$rs" = "Pass" ] && passed=$((passed + 1))
      r="${rq%%[ (,]*}"
      case " $seen " in *" $r "*) ;; *) seen="$seen$r " ;; esac
    done <<< "$(rows "$qa")"
    for r in $reqs; do
      case " $seen " in *" $r "*) covered=$((covered + 1)); continue ;; esac
      printf '%s\n' "$excused" | grep -qx "$r" && covered=$((covered + 1))
    done
    reqcol="$covered/$total"; rowcol="$passed/$nrows"
  else
    reqcol="no QA record"; rowcol="no QA record"
  fi
  lines="$lines$key	| $outcome | $intent | $spec | $key | $reqcol | $rowcol | $acceptance |
"
done

{
  printf '# Traceability\n\n'
  printf 'Generated by `.github/scripts/trace.sh` from the records in `docs/`. Do not edit by hand.\n\n'
  printf '| Outcome | Intent | Spec | Ticket | Requirements | Rows passed | Acceptance |\n'
  printf '| --- | --- | --- | --- | --- | --- | --- |\n'
  printf '%s' "$lines" | sed '/^$/d' | sort | cut -f2-
} > "$out"
echo "wrote $out"
